import{z as n,x as s,o as r,c as d,q as i,j as A,D as e,d as t,s as o,S as m,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"k₁ 窗口与分辨率增强","description":"","frontmatter":{"title":"k₁ 窗口与分辨率增强","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/k1-factor-window.md","filePath":"litho/k1-factor-window.md","lastUpdated":1791063341000}'),p={name:"litho/k1-factor-window.md"};function h(k,a,B,_,D,c){const l=s("Mermaid");return r(),d("div",null,[a[2]||(a[2]=i('<h1 id="k1-窗口与分辨率增强" tabindex="-1">k₁ 窗口与分辨率增强 <a class="header-anchor" href="#k1-窗口与分辨率增强" aria-label="Permalink to &quot;k₁ 窗口与分辨率增强&quot;">​</a></h1><div class="epigraph"><p>$k_1$ 把「这一层还印不印得动」收成无量纲数；分辨率增强不改 $\\lambda$ 与 $\\mathrm{NA}$，只把可印窗口往更低的 $k_1$ 推。</p><footer>—— 据 Mack、Levinson 对 $k_1$ 工艺因子与 RET 的产线定义整理</footer></div><p><a href="/litho/halfpitch-vs-cd">上一课</a>（半节距对线宽）。在此之上，临界尺寸钉成 \\(\\mathrm{CD}=k_1\\lambda/\\mathrm{NA}\\)，并指出 \\(k_1\\) 不是显微镜的 0.61。缺口是：产线并不是选定一个 \\(k_1\\) 再开印——它有一块随节距、图形维度和工艺容差变化的可印窗口；分辨率增强（RET）的工作就是让目标层落在窗口里面。窗口对剂量误差还剩多少宽容，留给<a href="/litho/exposure-latitude">下一课</a>的曝光宽容度。波长不能连续拧，那是后面<a href="/litho/litho-wavelengths">波长台阶</a>课的整栈替换；离轴图案、相移膜系、OPC 算法各自成课，本课不提前做目录。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把上一课的式子反过来写</p> \\[k_1=\\mathrm{HP}\\cdot\\frac{\\mathrm{NA}}{\\lambda}, \\]<p>半节距 \\(\\mathrm{HP}\\) 一旦给定，\\(k_1\\) 就是这一层在这台镜头上的工作点。工作点太高，浪费 \\(\\mathrm{NA}\\)；太低，空中像对比不够，<a href="/litho/ed-process-window">曝光–散焦窗口</a>收成一条缝。缺口因此是把 \\(k_1\\) 从「公式里的一个数」改成「窗口」：哪些节距还活着、二维拐角比一维栅差多少、RET 买的是窗口面积而不是名义分辨率。</p><p>单次曝光的经验地板大约 0.25，上一课已经说过。本课要补的是：靠近地板时，不是所有图形类别同时死——密线栅可以靠两束成像再撑一档，孤立线和孔先关窗。所以「这一层的 \\(k_1\\)」必须声明图形。</p><p><span class="marginnote">数字实例：取 \\(\\lambda=193\\) nm、\\(\\mathrm{NA}=1.35\\)、\\(k_1=0.27\\)，则 \\(\\mathrm{CD}=0.27\\times193/1.35\\approx39\\) nm。若 \\(k_1\\) 退到 0.35，同一台镜头只能印约 50 nm——镜头没换，窗口说了算。</span></p><h3 id="窗口不是瑞利距的百分比" tabindex="-1">窗口不是瑞利距的百分比 <a class="header-anchor" href="#窗口不是瑞利距的百分比" aria-label="Permalink to &quot;窗口不是瑞利距的百分比&quot;">​</a></h3><p>显微镜判据给出一个刚可分辨的距离。光刻窗口问的是：剂量漂几个百分点、焦距漂几十纳米，CD 是否仍在规格内。同一 \\(k_1\\) 下，照明一变，窗口可从可用变成零。因此 RET 的成绩单是重叠工艺窗口，不是又把 \\(\\lambda/\\mathrm{NA}\\) 乘了一个更小的系数。</p><p><span class="marginnote">同一 \\(\\lambda\\)、同一 \\(\\mathrm{NA}\\)，逻辑金属的有效 \\(k_1\\) 和 SRAM 栅的有效 \\(k_1\\) 可以差一截。报节点时写「\\(k_1=0.31\\)」而不写层别，等于没报。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先算目标半节距对应的 \\(k_1\\)，再问常规圆照明下 NILS 够不够。不够，就动三个不改波长的旋钮：照明光瞳（把能量挪到能进光瞳的级）、掩模复透过率（压零级、造相消）、物体预畸变（OPC/ILT）。三者都在同一套部分相干成像里，只是改 TCC 的源、改物体频谱、或两者一起改。</p><p>本课只给判据：RET 成功与否看 \\(k_1\\) 窗口有没有回到可量产面积。具体光瞳画成偶极、掩模做成衰减相移，是后面 DUV 课序的题目。</p><h3 id="二维比一维更早撞墙" tabindex="-1">二维比一维更早撞墙 <a class="header-anchor" href="#二维比一维更早撞墙" aria-label="Permalink to &quot;二维比一维更早撞墙&quot;">​</a></h3><p>一维密栅可以做成近两束，有效 \\(k_1\\) 能贴近地板。二维接触孔、拐角、线端缩短需要的空间频率是各向同性的，同一数值 \\(k_1\\) 下窗口窄得多。这就是为什么「演示了 0.27 的线栅」不能外推成逻辑后段可印。后课的多重曝光，本质是把二维目标拆回若干张较高 \\(k_1\\) 的曝光。</p>',17)),(r(),A(m,null,{default:e(()=>[o(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20HP%5B%22%E7%9B%AE%E6%A0%87%E5%8D%8A%E8%8A%82%E8%B7%9D%22%5D%20--%3E%20K1%5B%22k%E2%82%81%20%3D%20HP%C2%B7NA%2F%CE%BB%22%5D%0A%20%20K1%20--%3E%20WIN%5B%22%E5%8F%AF%E5%8D%B0%E7%AA%97%E5%8F%A3%22%5D%0A%20%20RET%5B%22RET%3A%20%E7%85%A7%E6%98%8E%20%2F%20%E6%8E%A9%E6%A8%A1%20%2F%20OPC%22%5D%20--%3E%20WIN%0A%20%20WIN%20--%3E%20OK%5B%22%E7%AA%97%E5%8F%A3%E9%9D%A2%E7%A7%AF%E5%8F%AF%E9%87%8F%E4%BA%A7%22%5D%0A%20%20WIN%20--%3E%20LOW%5B%22%E6%92%9E%E5%8D%95%E6%AC%A1%E5%9C%B0%E6%9D%BF%20%E2%86%92%20%E5%90%8E%E8%AF%BE%E6%8D%A2%20%CE%BB%20%E6%88%96%E5%88%86%E8%A7%A3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[t("\\(k_1\\) 低，意味着目标频率靠近光瞳截止。零级偏置相对变大，对比度掉，NILS 掉，剂量灵敏度变差——光学链在"),E("a",{href:"/litho/aerial-image-contrast"},"空中像"),t("上已经写过。RET 的机制是同一句话的工程化：改哪些级进光瞳、级的相对相位，让截止附近仍有可用调制。它不增加 \\(\\mathrm{NA}\\)，也不缩短 \\(\\lambda\\)，所以焦深的 \\(\\mathrm{NA}^2\\) 惩罚不会被 RET 取消；有时两束成像反而买回一点轴向窗口。")],-1)),a[5]||(a[5]=E("p",null,"胶的 \\(\\gamma\\) 可以切锐空中像，等效上让同一光学 \\(k_1\\) 变得「能用」，但切的是噪声和扩散一起。把胶衬度算进 \\(k_1\\) 可以，把它当成免费的分辨率旋钮不行。化学细节在抗蚀剂课程，本课只承认 \\(k_1\\) 含工艺。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：NILS 像斜坡的陡度。\\(k_1\\) 高时，强度曲线在目标线宽处像悬崖，剂量抖 2% 线宽几乎不动；\\(k_1\\) 低时变成缓坡，同样 2% 的抖动就把线宽推出规格。窗口收窄不是「印不出」，而是「印得出但站不稳」。")],-1)),(r(),A(m,null,{default:e(()=>[o(l,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%20k%E2%82%81%20%E4%B8%8B%E8%B0%81%E5%85%88%E5%85%B3%E7%AA%97%22%5D%20--%3E%20DENSE%5B%22%E4%B8%80%E7%BB%B4%E5%AF%86%E7%BA%BF%E6%A0%85%22%5D%0A%20%20Q%20--%3E%20ISO%5B%22%E5%AD%A4%E7%AB%8B%E7%BA%BF%20%2F%20%E7%BA%BF%E7%AB%AF%22%5D%0A%20%20Q%20--%3E%20HOLE%5B%22%E4%BA%8C%E7%BB%B4%E6%8E%A5%E8%A7%A6%E5%AD%94%20%2F%20%E6%8B%90%E8%A7%92%22%5D%0A%20%20DENSE%20--%3E%7C%22%E8%BF%91%E4%B8%A4%E6%9D%9F%E6%88%90%E5%83%8F%22%7C%20OK%5B%22%E7%AA%97%E5%8F%A3%E6%9C%80%E5%AE%BD%22%5D%0A%20%20ISO%20--%3E%20MID%5B%22%E7%AA%97%E5%8F%A3%E6%94%B6%E7%AA%84%22%5D%0A%20%20HOLE%20--%3E%7C%22%E9%9C%80%E8%A6%81%E5%90%84%E5%90%91%E5%90%8C%E6%80%A7%E9%A2%91%E7%8E%87%22%7C%20DEAD%5B%22%E6%9C%80%E6%97%A9%E5%85%B3%E7%AA%97%22%5D%0A%20%20DEAD%20--%3E%20FIX%5B%22%E6%8B%86%E5%9B%9E%E5%A4%9A%E5%BC%A0%E9%AB%98%20k%E2%82%81%20%E6%9B%9D%E5%85%89%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p>窗口随图形类别裂开：一层里最难的图形决定这一层能不能单次过。SMO 在光瞳上为最难的那一族搬家，必然牺牲另一族的余量。因此 \\(k_1\\) 窗口是向量，不是全场一个标量；报「本机台 \\(k_1=0.28\\)」必须附图形与照明。</p><p><span class="marginnote">多重图形不改单次曝光的 \\(k_1\\) 定义。每一次曝光仍要落在自己的窗口里。不要用最终金属节距反推单次 \\(k_1\\) 却宣称「打破了 0.25」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(k_1\\) 窗口不含套刻、缺陷、产能。多重图形把最终节距降下去，每一次曝光自己的 \\(k_1\\) 仍须落在窗口内——不要把「SAQP 之后的节距」代回式子再宣称单次 \\(k_1\\) 破了 0.25。也不要在本课展开波长台阶：\\(\\lambda\\) 从 193 跳到 13.5 是后面波长台阶课的整栈替换，不是又一种 RET。</p><p>后课默认：说到「压 \\(k_1\\)」就是在固定 \\(\\lambda\\)、\\(\\mathrm{NA}\\) 下扩窗口；说到「换波长」才动 \\(\\lambda\\)。</p><p><span class="marginnote">常见误区：看到「7 nm 工艺」就代 \\(\\mathrm{CD}=k_1\\lambda/\\mathrm{NA}\\) 反推出「\\(k_1\\) 已破 0.2」。节点名是营销代号，不是任何一层的半节距；能代回式子的只有当次曝光掩模上的图形节距。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(k_1\\) 是工作点，可印性由窗口面积衡量，不由名义 CD 衡量。</li><li>RET 不改 \\(\\lambda\\) 与 \\(\\mathrm{NA}\\)，只改哪些衍射级如何干涉。</li><li>一维栅与二维孔的有效 \\(k_1\\) 不可互换。</li><li>单次曝光地板约 0.25 仍然成立；再往下是分解或换波长。</li><li>窗口的剂量宽容是下一课；波长台阶在后面的波长课，本课不列光源年表。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>；Levinson, <em>Principles of Lithography</em>。</li></ul>',8))])}const C=n(p,[["render",h]]);export{u as __pageData,C as default};
